//! PR18L modifier-stack semantics checked against the Blender 5.2.2 oracle.
//!
//! `tests/fixtures/pr18l_stack/expected.json` is generated by `generate.py` from Blender. Each case
//! records its operation `steps`, Blender's result per step (`step_results`; `CANCELLED` is a move
//! refusal), the Blender stack order, the active stack per purpose, and the viewport (Preview) and
//! render (Render) vertex count, face count and position hash.
//!
//! Operation mapping: `create` -> `modifier.create` (top-level `show_viewport`/`show_render`),
//! `pin` -> `modifier.update` with `set.params` carrying `use_pin_to_last`, `visibility` ->
//! `modifier.update` with `set.show_*`, `move` -> `modifier.reorder` with `to_index`,
//! `delete` -> `modifier.delete`.
//!
//! Hash contract (identical to `blender_oracle.py`): each evaluated vertex position is formatted with
//! `{:.5}` (`-0.00000` becomes `0.00000`), the `"x y z"` lines are sorted bytewise, each followed by
//! `\n`, and the lowercase hex SHA-256 of that UTF-8 payload is compared.

use std::{collections::BTreeMap, error::Error, fmt::Debug, fs, path::PathBuf};

use glam::DVec3;
use potter_core::{
    error::PotError,
    eval::{EvaluationContext, EvaluationPurpose, Snapshot},
    model::{Id, SceneDoc},
    ops,
};
use serde_json::{Map, Value, json};
use sha2::{Digest, Sha256};

type TestResult<T> = Result<T, Box<dyn Error>>;

const SCENE_ID: &str = "00000000-0000-4000-8000-000000000000";
const OBJECT: &str = "cube";

#[derive(Debug, PartialEq, Eq)]
struct Measured {
    vertices: usize,
    faces: usize,
    position_sha: String,
}

struct Kind {
    potter_type: String,
    params: Map<String, Value>,
}

fn fixture() -> TestResult<Value> {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "tests",
        "fixtures",
        "pr18l_stack",
        "expected.json",
    ]
    .iter()
    .collect();
    Ok(serde_json::from_slice(&fs::read(path)?)?)
}

fn json_str<'a>(value: &'a Value, key: &str) -> TestResult<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("fixture field `{key}` must be a string").into())
}

fn json_usize(value: &Value, key: &str) -> TestResult<usize> {
    let number = value
        .get(key)
        .and_then(Value::as_u64)
        .ok_or_else(|| format!("fixture field `{key}` must be an integer"))?;
    Ok(usize::try_from(number)?)
}

fn json_strings(value: &Value) -> TestResult<Vec<String>> {
    value
        .as_array()
        .ok_or("fixture stack must be an array")?
        .iter()
        .map(|item| -> TestResult<String> {
            Ok(item
                .as_str()
                .ok_or("stack entries must be strings")?
                .to_owned())
        })
        .collect()
}

fn expected_measured(value: &Value) -> TestResult<Measured> {
    Ok(Measured {
        vertices: json_usize(value, "vertices")?,
        faces: json_usize(value, "faces")?,
        position_sha: json_str(value, "position_sha")?.to_owned(),
    })
}

fn load_kinds(fixture: &Value) -> TestResult<BTreeMap<String, Kind>> {
    let kinds = fixture
        .get("kinds")
        .and_then(Value::as_object)
        .ok_or("fixture kinds must be an object")?;
    let mut parsed = BTreeMap::new();
    for (name, kind) in kinds {
        let params = kind
            .get("params")
            .and_then(Value::as_object)
            .ok_or("fixture kind params must be an object")?
            .clone();
        parsed.insert(
            name.clone(),
            Kind {
                potter_type: json_str(kind, "potter_type")?.to_owned(),
                params,
            },
        );
    }
    Ok(parsed)
}

fn fixed5(value: f64) -> String {
    let text = format!("{value:.5}");
    if text == "-0.00000" {
        "0.00000".to_owned()
    } else {
        text
    }
}

fn position_sha(positions: &[DVec3]) -> String {
    let mut lines: Vec<String> = positions
        .iter()
        .map(|point| {
            format!(
                "{} {} {}",
                fixed5(point.x),
                fixed5(point.y),
                fixed5(point.z)
            )
        })
        .collect();
    lines.sort_unstable();
    let mut payload = String::new();
    for line in &lines {
        payload.push_str(line);
        payload.push('\n');
    }
    hex::encode(Sha256::digest(payload.as_bytes()))
}

fn ensure_eq<T: PartialEq + Debug>(actual: &T, expected: &T, what: &str) -> TestResult<()> {
    if actual == expected {
        Ok(())
    } else {
        Err(format!("{what}: expected {expected:?}, got {actual:?}").into())
    }
}

fn apply_one(doc: &SceneDoc, operation: &Value) -> Result<SceneDoc, PotError> {
    let batch = json!({
        "schema_version": 1,
        "base_revision": doc.revision,
        "operations": [operation],
    });
    Ok(ops::apply_batch(doc, &batch)?.doc)
}

fn stack_ids(doc: &SceneDoc, purpose: Option<EvaluationPurpose>) -> TestResult<Vec<String>> {
    let node = doc
        .nodes
        .get(&Id::new(OBJECT)?)
        .ok_or("cube node is missing")?;
    Ok(node
        .modifiers
        .iter()
        .filter(|modifier| purpose.is_none_or(|wanted| modifier.is_active(wanted)))
        .map(|modifier| modifier.id.to_string())
        .collect())
}

fn measure(doc: &SceneDoc, purpose: EvaluationPurpose) -> TestResult<Measured> {
    let snapshot = Snapshot::evaluate(
        doc,
        &EvaluationContext {
            purpose,
            ..EvaluationContext::default()
        },
    )?;
    ensure_eq(&snapshot.purpose, &purpose, "snapshot purpose")?;
    let mesh = snapshot
        .meshes
        .get(&Id::new(OBJECT)?)
        .ok_or("evaluated cube mesh is missing")?;
    let positions: Vec<DVec3> = mesh.vertices.iter().map(|vertex| vertex.co).collect();
    Ok(Measured {
        vertices: mesh.vertices.len(),
        faces: mesh.faces.len(),
        position_sha: position_sha(&positions),
    })
}

/// Visibility fields for a create or update. In the `enabled=false` variant, a step that hides
/// both purposes is expressed as Potter's global `enabled: false`, which Blender cannot express.
fn visibility_fields(step: &Value, enabled_false: bool) -> Map<String, Value> {
    let mut fields = Map::new();
    for key in ["show_viewport", "show_render"] {
        if let Some(flag) = step.get(key) {
            fields.insert(key.to_owned(), flag.clone());
        }
    }
    if enabled_false
        && fields.get("show_viewport") == Some(&json!(false))
        && fields.get("show_render") == Some(&json!(false))
    {
        fields.clear();
        fields.insert("enabled".to_owned(), json!(false));
    }
    fields
}

fn step_operation(
    step: &Value,
    kinds: &BTreeMap<String, Kind>,
    kind_of: &mut BTreeMap<String, String>,
    enabled_false: bool,
) -> TestResult<Value> {
    let action = json_str(step, "action")?;
    let name = json_str(step, "name")?;
    match action {
        "create" => {
            let kind_name = json_str(step, "kind")?;
            let kind = kinds
                .get(kind_name)
                .ok_or_else(|| format!("unknown kind `{kind_name}`"))?;
            kind_of.insert(name.to_owned(), kind_name.to_owned());
            let mut operation = json!({
                "op": "modifier.create",
                "target": {"id": OBJECT},
                "id": name,
                "type": kind.potter_type,
                "params": kind.params,
            });
            operation
                .as_object_mut()
                .ok_or("operation must be an object")?
                .extend(visibility_fields(step, enabled_false));
            Ok(operation)
        }
        "pin" => {
            let kind_name = kind_of
                .get(name)
                .ok_or_else(|| format!("pin before create for `{name}`"))?;
            let kind = kinds
                .get(kind_name)
                .ok_or_else(|| format!("unknown kind `{kind_name}`"))?;
            let mut params = kind.params.clone();
            params.insert(
                "use_pin_to_last".to_owned(),
                step.get("value").cloned().ok_or("pin step needs value")?,
            );
            Ok(json!({
                "op": "modifier.update",
                "target": {"id": OBJECT},
                "id": name,
                "set": {"params": params},
            }))
        }
        "visibility" => Ok(json!({
            "op": "modifier.update",
            "target": {"id": OBJECT},
            "id": name,
            "set": visibility_fields(step, enabled_false),
        })),
        "move" => Ok(json!({
            "op": "modifier.reorder",
            "target": {"id": OBJECT},
            "id": name,
            "to_index": step.get("to_index").cloned().ok_or("move step needs to_index")?,
        })),
        "delete" => Ok(json!({
            "op": "modifier.delete",
            "target": {"id": OBJECT},
            "id": name,
        })),
        other => Err(format!("unknown step action `{other}`").into()),
    }
}

fn check_case(
    name: &str,
    case: &Value,
    kinds: &BTreeMap<String, Kind>,
    enabled_false: bool,
) -> TestResult<()> {
    let steps = case
        .get("steps")
        .and_then(Value::as_array)
        .ok_or("case steps must be an array")?;
    let step_results = case
        .get("step_results")
        .and_then(Value::as_array)
        .ok_or("case step_results must be an array")?;
    ensure_eq(&step_results.len(), &steps.len(), "step_results length")?;

    let mut doc = apply_one(
        &SceneDoc::new(SCENE_ID.to_owned()),
        &json!({"op": "node.create", "id": OBJECT, "kind": "box", "params": {"size": 2.0}}),
    )?;
    let mut kind_of = BTreeMap::new();
    for (step, result) in steps.iter().zip(step_results) {
        let operation = step_operation(step, kinds, &mut kind_of, enabled_false)?;
        if result.as_str() == Some("CANCELLED") {
            // Blender refused this step: Potter may reject it or accept it without changing the stack.
            let before = stack_ids(&doc, None)?;
            if let Ok(next) = apply_one(&doc, &operation) {
                ensure_eq(
                    &stack_ids(&next, None)?,
                    &before,
                    "refused step changed the stack",
                )?;
                doc = next;
            }
        } else {
            doc = apply_one(&doc, &operation)?;
        }
    }

    ensure_eq(
        &stack_ids(&doc, None)?,
        &json_strings(case.get("stack").ok_or("case stack missing")?)?,
        &format!("{name} stack"),
    )?;
    ensure_eq(
        &stack_ids(&doc, Some(EvaluationPurpose::Preview))?,
        &json_strings(
            case.get("viewport_stack")
                .ok_or("case viewport_stack missing")?,
        )?,
        &format!("{name} viewport stack"),
    )?;
    ensure_eq(
        &stack_ids(&doc, Some(EvaluationPurpose::Render))?,
        &json_strings(
            case.get("render_stack")
                .ok_or("case render_stack missing")?,
        )?,
        &format!("{name} render stack"),
    )?;
    let viewport = case.get("viewport").ok_or("case viewport missing")?;
    ensure_eq(
        &measure(&doc, EvaluationPurpose::Preview)?,
        &expected_measured(viewport)?,
        &format!("{name} viewport"),
    )?;
    let render = case.get("render").ok_or("case render missing")?;
    ensure_eq(
        &measure(&doc, EvaluationPurpose::Render)?,
        &expected_measured(render)?,
        &format!("{name} render"),
    )?;
    Ok(())
}

#[test]
fn blender_modifier_stack_semantics_match_potter() -> TestResult<()> {
    let fixture = fixture()?;
    let kinds = load_kinds(&fixture)?;
    let cases = fixture
        .get("cases")
        .and_then(Value::as_object)
        .ok_or("fixture cases must be an object")?;
    let mut failures = Vec::new();
    for (name, case) in cases {
        if let Err(error) = check_case(name, case, &kinds, false) {
            failures.push(format!("{name}: {error}"));
        }
        if case
            .get("potter_equivalent_variant")
            .and_then(Value::as_str)
            == Some("enabled_false")
            && let Err(error) = check_case(name, case, &kinds, true)
        {
            failures.push(format!("{name} (enabled=false variant): {error}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    Ok(())
}

#[test]
fn blender_oracle_self_checks_hold() -> TestResult<()> {
    let fixture = fixture()?;
    let checks = fixture
        .get("checks")
        .and_then(Value::as_object)
        .ok_or("fixture checks must be an object")?;
    for (name, passed) in checks {
        ensure_eq(&passed.as_bool(), &Some(true), name)?;
    }
    Ok(())
}
